previewCss:
.darma-loader-balance-scale {
  position: relative;
  width: 52px;
  height: 48px;
}
.darma-loader-balance-scale::before {
  content: "";
  position: absolute;
  bottom: 4px;
  left: 50%;
  width: 4px;
  height: 34px;
  margin-left: -2px;
  border-radius: 2px;
  background: #4338ca;
}
.darma-loader-balance-scale::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 24px;
  height: 5px;
  margin-left: -12px;
  border-radius: 2px;
  background: #4338ca;
}
.darma-loader-balance-scale i {
  position: absolute;
  top: 8px;
  left: 50%;
  width: 40px;
  height: 4px;
  margin-left: -20px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  transform-origin: center;
  animation: darma-loader-balance-scale-tip 2s ease-in-out infinite;
}
.darma-loader-balance-scale i::before {
  content: "";
  position: absolute;
  top: 2px;
  left: -4px;
  width: 14px;
  height: 8px;
  border: 2px solid var(--loader-color, #6366f1);
  border-top: 0;
  border-radius: 0 0 40% 40%;
  box-sizing: border-box;
}
.darma-loader-balance-scale i::after {
  content: "";
  position: absolute;
  top: 2px;
  right: -4px;
  width: 14px;
  height: 8px;
  border: 2px solid var(--loader-color, #6366f1);
  border-top: 0;
  border-radius: 0 0 40% 40%;
  box-sizing: border-box;
}
@keyframes darma-loader-balance-scale-tip {
  0%, 100% { transform: rotate(-9deg); }
  50% { transform: rotate(9deg); }
}

